// NWD i NWW n liczb. Wejście: n, potem n liczb dodatnich. Zakładamy, że NWW mieści się w long long.
#include <bits/stdc++.h>
using namespace std;

long long nwd(long long a, long long b) {        // algorytm Euklidesa (iteracyjnie)
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

long long nww(long long a, long long b) {
    return a / nwd(a, b) * b;                      // najpierw dzielimy — mniejsze ryzyko przepełnienia
}

int main() {
    int n;
    cin >> n;
    long long g = 0, l = 1;                        // gcd(0, x) = x, lcm(1, x) = x
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        g = nwd(g, x);
        l = nww(l, x);
    }
    cout << g << " " << l << "\n";
}

