// Rozwiązanie a*x + b*y = c (a, b > 0, |c| <= 1e18) z najmniejszym nieujemnym x, albo NIE.
#include <bits/stdc++.h>
using namespace std;

long long extgcd(long long a, long long b, long long &x, long long &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    long long x1, y1;
    long long g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int main() {
    long long a, b, c;
    cin >> a >> b >> c;
    long long x, y;
    long long g = extgcd(a, b, x, y);              // a*x + b*y = g
    if (c % g != 0) { cout << "NIE\n"; return 0; }
    long long step = b / g;                        // x zmienia się o wielokrotności b/g
    __int128 X = (__int128)x * (c / g) % step;     // __int128: x * (c/g) może przekroczyć long long
    if (X < 0) X += step;
    __int128 Y = ((__int128)c - (__int128)a * X) / b;   // dzieli się dokładnie
    cout << (long long)X << " " << (long long)Y << "\n";
}

// Wersja iteracyjna (bez rekurencji). Zwraca g, ustawia x, y: a*x + b*y = g.
long long extgcdIter(long long a, long long b, long long &x, long long &y) {
    long long x0 = 1, y0 = 0, x1 = 0, y1 = 1;
    while (b != 0) {
        long long q = a / b;
        tie(a, b) = make_pair(b, a - q * b);
        tie(x0, x1) = make_pair(x1, x0 - q * x1);
        tie(y0, y1) = make_pair(y1, y0 - q * y1);
    }
    x = x0; y = y0;
    return a;
}

