// Sito Eratostenesa: liczba liczb pierwszych <= N oraz największa z nich (-1, gdy brak).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<bool> isPrime(N + 1, true);           // vector<bool> = 1 bit na liczbę
    isPrime[0] = false;
    if (N >= 1) isPrime[1] = false;              // 0 i 1 NIE są pierwsze
    for (long long p = 2; p * p <= N; p++)
        if (isPrime[p])
            for (long long q = p * p; q <= N; q += p)   // od p*p, krok p
                isPrime[q] = false;

    int cnt = 0, last = -1;
    for (int i = 2; i <= N; i++)
        if (isPrime[i]) { cnt++; last = i; }
    cout << cnt << " " << last << "\n";
}

// Sito najmniejszych dzielników pierwszych: spf[x] = najmniejsza liczba pierwsza dzieląca x.
// Rozkład x na czynniki: dziel przez spf[x], aż zostanie 1 — O(log x).
const int MAXN = 1000000;
int spf[MAXN + 1];

void buildSpf() {
    for (int i = 2; i <= MAXN; i++)
        if (spf[i] == 0)                               // i jest pierwsza
            for (long long j = i; j <= MAXN; j += i)
                if (spf[j] == 0) spf[j] = i;
}

vector<int> factorize(int x) {                         // czynniki pierwsze z powtórzeniami
    vector<int> f;
    while (x > 1) { f.push_back(spf[x]); x /= spf[x]; }
    return f;
}

// Sito liniowe O(N): każda liczba złożona skreślana dokładnie raz — przez swój najmniejszy dzielnik pierwszy.
vector<int> primes;
vector<int> lp;                                        // lp[x] = najmniejszy dzielnik pierwszy x

void linearSieve(int N) {
    lp.assign(N + 1, 0);
    for (int i = 2; i <= N; i++) {
        if (lp[i] == 0) { lp[i] = i; primes.push_back(i); }
        for (int p : primes) {
            if (p > lp[i] || 1LL * i * p > N) break;
            lp[i * p] = p;
        }
    }
}

// Sito segmentowe: liczba liczb pierwszych w [L, R], R <= 1e12, R - L <= ~1e7.
#include <bits/stdc++.h>
using namespace std;

int main() {
    long long L, R;
    cin >> L >> R;
    long long lim = sqrtl((long double)R) + 1;
    vector<bool> small(lim + 1, true);                 // zwykłe sito do sqrt(R)
    vector<long long> primes;
    for (long long i = 2; i <= lim; i++)
        if (small[i]) {
            primes.push_back(i);
            for (long long j = i * i; j <= lim; j += i) small[j] = false;
        }
    vector<bool> seg(R - L + 1, true);                 // seg[i] <=> L + i jest pierwsza
    for (long long p : primes) {
        long long start = max(p * p, (L + p - 1) / p * p);   // pierwsza wielokrotność p >= L (i >= p*p)
        for (long long j = start; j <= R; j += p) seg[j - L] = false;
    }
    if (L <= 1) for (long long x = L; x <= min(R, 1LL); x++) seg[x - L] = false;   // 0 i 1
    cout << count(seg.begin(), seg.end(), true) << "\n";
}

