// Rozkład n <= 1e12 na czynniki: wypisuje pary "p a" (p^a) w kolejności rosnącej.
#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<pair<long long, int>> f;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d != 0) continue;
        int a = 0;
        while (n % d == 0) { n /= d; a++; }
        f.push_back({d, a});
    }
    if (n > 1) f.push_back({n, 1});          // pozostała liczba pierwsza > sqrt
    for (auto [p, a] : f) cout << p << " " << a << "\n";
}

// Wiele liczb <= 1e9: dzielimy tylko przez liczby pierwsze <= sqrt(1e9) ~ 31623 (jest ich 3401).
vector<int> smallPrimes;
void initPrimes(int lim = 31623) {
    vector<bool> s(lim + 1, true);
    for (int i = 2; i <= lim; i++)
        if (s[i]) {
            smallPrimes.push_back(i);
            for (long long j = 1LL * i * i; j <= lim; j += i) s[j] = false;
        }
}
vector<pair<int,int>> factorizeFast(int n) {
    vector<pair<int,int>> f;
    for (int p : smallPrimes) {
        if (1LL * p * p > n) break;
        if (n % p) continue;
        int a = 0;
        while (n % p == 0) { n /= p; a++; }
        f.push_back({p, a});
    }
    if (n > 1) f.push_back({n, 1});
    return f;
}

