// φ(n) dla n <= 1e12 przez rozkład w O(sqrt n).
#include <bits/stdc++.h>
using namespace std;

long long phi(long long n) {
    long long res = n;
    for (long long p = 2; p * p <= n; p++)
        if (n % p == 0) {
            while (n % p == 0) n /= p;
            res = res / p * (p - 1);        // mnożymy przez (1 - 1/p) bez ułamków
        }
    if (n > 1) res = res / n * (n - 1);     // ostatni czynnik pierwszy
    return res;
}

int main() {
    long long n;
    cin >> n;
    cout << phi(n) << "\n";
}

// Sito φ: phi[i] dla wszystkich i <= N, O(N log log N).
vector<int> phiSieve(int N) {
    vector<int> ph(N + 1);
    iota(ph.begin(), ph.end(), 0);           // ph[i] = i
    for (int p = 2; p <= N; p++)
        if (ph[p] == p)                      // p nietknięte => pierwsze
            for (int m = p; m <= N; m += p)
                ph[m] -= ph[m] / p;          // ph[m] *= (1 - 1/p)
    return ph;
}

