// CRT ogólne: k równań x ≡ a_i (mod m_i). Wypisuje najmniejsze x >= 0 i lcm modułów, albo -1.
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1, g = extgcd(b, a % b, x1, y1);
    x = y1; y = x1 - (a / b) * y1;
    return g;
}

// łączy x ≡ a1 (mod m1) z x ≡ a2 (mod m2); false, gdy sprzeczne
bool merge(ll &a1, ll &m1, ll a2, ll m2) {
    ll p, q;
    ll g = extgcd(m1, m2, p, q);                    // m1*p + m2*q = g
    if ((a2 - a1) % g != 0) return false;
    ll mg = m2 / g;
    lll t = (lll)((a2 - a1) / g % mg) * (p % mg) % mg;   // t ≡ (a2-a1)/g * inv(m1/g) (mod m2/g)
    if (t < 0) t += mg;
    lll L = (lll)m1 / g * m2;                       // lcm(m1, m2), zakładamy że mieści się w ll
    lll x = ((lll)a1 + (lll)m1 * t) % L;
    if (x < 0) x += L;
    a1 = (ll)x; m1 = (ll)L;
    return true;
}

int main() {
    int k;
    cin >> k;
    ll a = 0, m = 1;                                // x ≡ 0 (mod 1) — neutralne
    bool ok = true;
    for (int i = 0; i < k; i++) {
        ll ai, mi;
        cin >> ai >> mi;
        ai %= mi; if (ai < 0) ai += mi;
        if (ok) ok = merge(a, m, ai, mi);
    }
    if (!ok) cout << -1 << "\n";
    else cout << a << " " << m << "\n";
}

